# vaddr->file: sections; use readelf parse
import subprocess,re
out=subprocess.check_output(['readelf','-SW','libs/libiqa.so'],text=True)
secs=[]
for l in out.splitlines():
    m=re.match(r'\s*\[\s*\d+\]\s+(\S+)\s+\S+\s+([0-9a-f]+)\s+([0-9a-f]+)\s+([0-9a-f]+)',l)
    if m: secs.append((m.group(1),int(m.group(2),16),int(m.group(3),16),int(m.group(4),16)))
def v2f(v):
    for n,addr,off,size in secs:
        if addr<=v<addr+size: return off+(v-addr)
    return v
def cstr(v):
    o=v2f(v); e=d.index(b'\0',o); return d[o:e].decode(errors='replace')
# find pointer to layer_registry symbol address
base=0xb19cc0
# entries are 16 bytes? inspect first 64 bytes
for i in range(6):
    a,b=struct.unpack_from('<QQ',d,v2f(base)+i*16)
    print(i,a,hex(b),cstr(a) if a>0x1000 else a)
